def _ensure_data_dir():
    if not os.path.exists(DATA_DIR):
        os.makedirs(DATA_DIR, exist_ok=True)


def _load_all_profiles() -> Dict[str, Dict[str, Any]]:
    """Load profiles from disk or seed file if not present, deep merging new institutional fields."""
    _ensure_data_dir()
    if not os.path.exists(PROFILES_FILE):
        _save_all_profiles(SEED_PROFILES)
        return SEED_PROFILES.copy()

    try:
        with open(PROFILES_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
            # Merge with any missing seed keys or new institutional fields
            def _deep_merge(target, source):
                mod = False
                for sk, sv in source.items():
                    if sk not in target:
                        target[sk] = sv
                        mod = True
                    elif isinstance(target[sk], dict) and isinstance(sv, dict):
                        if _deep_merge(target[sk], sv):
                            mod = True
                return mod

            updated = False
            for k, v in SEED_PROFILES.items():
                if k not in data:
                    data[k] = v
                    updated = True
                else:
                    if _deep_merge(data[k], v):
                        updated = True
            if updated:
                _save_all_profiles(data)
            return data
    except Exception as e:
        print(f"[TokenDB Error] Failed to read {PROFILES_FILE}: {e}")
        return SEED_PROFILES.copy()


def _save_all_profiles(data: Dict[str, Dict[str, Any]]) -> bool:
    """Save full profiles dict to disk."""
    _ensure_data_dir()
    try:
        with open(PROFILES_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
        return True
    except Exception as e:
        print(f"[TokenDB Error] Failed to write {PROFILES_FILE}: {e}")
        return False


def get_profile(token_id: str) -> Optional[Dict[str, Any]]:
    """Retrieve deep tokenomics profile by token_id, symbol, or alias, guaranteeing institutional fields."""
    if not token_id:
        return None
    token_id = token_id.strip().lower()
    profiles = _load_all_profiles()
    
    alias_map = {
        "bnb": "binancecoin",
        "binance-coin": "binancecoin",
        "mkr": "makerdao",
        "maker": "makerdao",
        "eth": "ethereum",
        "btc": "bitcoin",
        "sol": "solana",
        "uni": "uniswap",
        "ray": "raydium",
        "hype": "hyperliquid",
        "tia": "celestia",
        "arb": "arbitrum",
        "op": "optimism",
        "wld": "worldcoin-wld"
    }
    
    target_id = alias_map.get(token_id, token_id)
    p = profiles.get(target_id)
    
    # Match by symbol or name fallback
    if not p:
        for pid, candidate in profiles.items():
            if candidate.get("symbol", "").lower() == token_id or pid == token_id.replace("-wld", "") or pid.startswith(token_id):
                p = candidate
                break

    if p:
        # Guarantee missing institutional fields exist
        for k, v in DEFAULT_INSTITUTIONAL_FIELDS.items():
            if k not in p:
                p[k] = v.copy() if isinstance(v, (dict, list)) else v
        return p
            
    return None


def save_profile(token_id: str, profile_data: Dict[str, Any]) -> bool:
    """Save or update a specific token profile in persistent local storage."""
    if not token_id:
        return False
    token_id = token_id.strip().lower()
    profiles = _load_all_profiles()
    profile_data["id"] = token_id
    profiles[token_id] = profile_data
    return _save_all_profiles(profiles)


def list_profiles() -> List[Dict[str, Any]]:
    """List all available token profiles in storage."""
    profiles = _load_all_profiles()
    return list(profiles.values())


def delete_profile(token_id: str) -> bool:
    """Delete a custom profile from storage."""
    token_id = token_id.strip().lower()
    profiles = _load_all_profiles()
    if token_id in profiles:
        del profiles[token_id]
        return _save_all_profiles(profiles)
    return False


def export_profiles_json() -> str:
    """Export all profiles as formatted JSON string."""
    profiles = _load_all_profiles()
    return json.dumps(profiles, indent=2)


def import_profiles_json(json_str: str) -> bool:
    """Import and merge JSON profiles into database."""
    try:
        new_data = json.loads(json_str)
        if isinstance(new_data, dict):
            current = _load_all_profiles()
            current.update(new_data)
            return _save_all_profiles(current)
        return False
    except Exception as e:
        print(f"[TokenDB Error] Import failed: {e}")
        return False
